"""Read-only, presentation-ready inspector for artifacts generated by the Java compiler.

Only the viewer is changed. Lexer/Parser/AST/Symbol Table/CodeGen remain the
source of truth: nothing on this page rebuilds a parse tree from source code.
"""
import json
from pathlib import Path
from flask import abort, jsonify, render_template_string, send_file, send_from_directory
from regenerate import COMPILER_OUTPUT_DIR

REPORTS_DIR = Path(COMPILER_OUTPUT_DIR).resolve().with_name("compiler_details")
TREE_FILES = {
    "python-parse": ("Python Parse Tree", "parse_tree_python.txt"),
    "jinja-parse": ("Jinja Parse Tree", "parse_tree_jinja.txt"),
    "python-ast": ("Python AST", "ast_python_tree.txt"),
    "jinja-ast": ("Jinja AST", "ast_jinja_tree.txt"),
    "css-ast": ("CSS AST", "ast_css_tree.txt"),
    "symbol-table": ("Symbol Table", "symbol_table.txt"),
}

