# يعرض هذا المسار الأشجار المحفوظة من مترجم جافا؛ لا يبني أشجارا جديدة من صفحات العرض.
def register_tree_viewer(app):
    """Register read-only inspector endpoints without altering Flask product routes."""

    @app.get("/compiler/assets/<filename>")
    def compiler_viewer_assets(filename):
        if filename not in {"tree_viewer.css", "tree_viewer.js", "validation.css", "validation.js"}:
            abort(404)
        return send_from_directory(Path(__file__).parent / "viewer_assets", filename)

    @app.get("/compiler/trees")
    def compiler_trees():
        return render_template_string(VIEWER_HTML, reports=TREE_FILES)

    @app.get("/compiler/context-module")
    def compiler_context_module():
        """Optional known module values from the compiler-produced context, not guessed."""
        context_path = REPORTS_DIR / "context_data.json"
        if not context_path.is_file():
            return jsonify({})
        try:
            with context_path.open(encoding="utf-8") as source:
                context = json.load(source)
            return jsonify(context.get("moduleData", {}))
        except (OSError, ValueError, TypeError):
            return jsonify({})

    @app.get("/compiler/tree-file/<key>")
    def compiler_tree_file(key):
        entry = TREE_FILES.get(key)
        if entry is None:
            abort(404)
        filepath = REPORTS_DIR / entry[1]
        if not filepath.is_file():
            abort(404)
        return send_file(filepath, mimetype="text/plain; charset=utf-8", as_attachment=False, conditional=False)
